      }
    ],
    "patient_family_realworld_adaptation": [
      {
        "event_id": "lite_evt_00124",
        "explanation": "Doctor addressed practical barriers like patient refusal to leave home and provided non-confrontational caregiving strategies.",
        "quote": "用“我们出去走一圈透透气”的方式哄她上车"
      }
    ]
  },
  "dimension_ratings": {
    "actionability_responsibility_chain": "good",
