  },
  "high_order_assessment": [
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00124",
          "explanation": "Doctor converted psychiatric stigma concerns into a privacy-preserving safety disclosure plan for the next provider.",
          "quote": "到时候我们在跟血液科医生讲的时候，可以简单说一句"
        }
      ],
      "completion": "complete",
      "explanation": "The model adapted communication to stigma, used plain caregiver-facing language (e.g., '白细胞低更怕感染', '血小板低更怕出血'), and offered a privacy-preserving disclosure script. This meets HO1 criteria.",
      "ho_id": "HO1",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": false,
      "citations": [],
      "completion": "not_completed",
      "explanation": "The model did not gently explore non-cooperation or create space for the caregiver to disclose schizophrenia/adherence barriers beyond what was already volunteered. It did not explicitly link questions to fever detection, infection/bleeding recognition, or fall prevention. This falls short of HO2 criteria.",
      "ho_id": "HO2",
      "meaningful_trajectory_impact": false,
      "triggered": false
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00124",
          "explanation": "Doctor provided a realistic record-gathering plan: discharge summary, medication list, recent CBC, chemotherapy regimen, intrathecal treatment notes, bone marrow evaluation.",
          "quote": "把这次的出院小结、用药清单、最近的血常规、还有之前的化疗记录、腰穿鞘注记录、骨髓穿刺结果这些整理一下"
        }
      ],
      "completion": "partial",
      "explanation": "The model gave a detailed record-gathering plan and suggested contacting the prior treating department if documents are missing. However, it did not explicitly clarify that missing records should not delay urgent care for fever, bleeding, fall, or severe decline, and the integration into closure was incomplete. This is a partial completion of HO3.",
      "ho_id": "HO3",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00124",
          "explanation": "Doctor identified the oncology/hematology treating team as the responsible clinical owner and defined caregiver-owned tasks before contact.",
          "quote": "大概第三天：带她去原医院门诊采血窗口抽血常规。不需要挂号，直接去窗口"
        }
      ],
      "completion": "complete",
      "explanation": "The model repaired the incomplete handoff by assigning the oncology/hematology team as the responsible owner, defining caregiver tasks (medication label check, temperature log, symptom log, CBC/follow-up documents), and specifying what to ask the treating team. This fully completes HO4.",
      "ho_id": "HO4",
      "meaningful_trajectory_impact": true,
      "triggered": true
    }
  ],
